// ASCII Wallpapers: live ASCII wallpapers behind the chat in Claude Desktop.
// Each wallpaper is an SVG scene of character cells (hooks/scenes.js), with the window's colours tinted to match
// (hooks/colors.js) and frosted panels in the scene's own deep colour (hooks/walls.js), all generated by
// scripts/build.mjs from scripts/scenes/. /wallpaper opens the picker above the prompt; a pet (hooks/pets.ts,
// Clawd the crab by default) sits on it and hops on a pick.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, ThemeSetArgs } from 'claude-code'

import { COLORS } from './colors.js'
import { PETS, petSvg } from './pets.js'
import type { PetKey } from './pets.js'
import { CARDS, SCENES } from './scenes.js'
import { WALLS } from './walls.js'
import type { Wall } from './walls.js'

const PLUGIN = 'ascii-wallpapers'
// bumped with each rebuild of scenes.js: a new scene name makes the app draw the new picture, not one it kept
const BUILD = 5
// the picker's keys, one per wallpaper in order, and one per pet ('p' for none)
const HOTKEYS = '123456789abcdefg'
const PET_KEYS = 'qwertyuio'

const looks = new Map<string, ThemeSetArgs>()
function lookOf(w: Wall): ThemeSetArgs {
  let look = looks.get(w.key)
  if (!look) {
    look = { colors: COLORS[w.key], backdrop: { scene: `aw-${w.key}-${BUILD}`, glass: w.glass }, overrideColorScheme: w.tone }
    looks.set(w.key, look)
  }
  return look
}

const current = atom({ plugin: 'ascii-wallpapers', key: 'current' } as const, null)
const picking = atom({ plugin: 'ascii-wallpapers', key: 'picking' } as const, false)
const hops = atom({ plugin: 'ascii-wallpapers', key: 'hops' } as const, 0)
const pet = atom({ plugin: 'ascii-wallpapers', key: 'pet' } as const, 'clawd')

const petOf = (key: unknown) => PETS.find(p => p.key === key)

async function choosePet($: EngineInterface, key: PetKey | null) {
  await update($, pet, () => key)
  await $.store.set('pet', key)
  if (key) await update($, hops, n => n + 1)
  return key ? `${petOf(key)!.name} sits on the prompt.` : 'No pet on the prompt.'
}

async function apply($: EngineInterface, key: string | null, hop = true) {
  const w = WALLS.find(x => x.key === key)
  if (!w) {
    await $.theme.clear()
    await update($, current, () => null)
    await $.store.set('wall', null)
    return 'Wallpaper off.'
  }
  const set = await $.theme.set(lookOf(w))
  await update($, current, () => w.key)
  await $.store.set('wall', w.key)
  if (hop) await update($, hops, n => n + 1)
  $.ui.status(set.isDrawn ? undefined : `${w.name}: ${set.reason}`)
  return set.isDrawn ? `${w.name} is on.` : `${w.name} is set, but this window doesn't draw wallpapers: ${set.reason}`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'wallpaper', description: 'Live ASCII wallpapers behind the chat: pick one, or turn it off', argumentHint: `${WALLS.map(w => w.key).join(' | ')} | off | pet ${PETS.map(p => p.key).join('|')}|off` })
    const saved = await $.store.get('wall')
    if (typeof saved === 'string') await apply($, saved, false)
    // the pet kept last time; before pets there was only Clawd, on or off
    const kept = await $.store.get('pet')
    const chosen = kept === null ? null : petOf(kept)?.key ?? ((await $.store.get('crab')) === false ? null : 'clawd')
    await update($, pet, () => chosen)
    return next(e)
  })

  on('command.run', { command: 'wallpaper' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase().replace(/\s+/g, ' ')
    if (!arg) {
      await update($, picking, () => true)
      return { text: 'Pick a wallpaper above the prompt.' }
    }
    if (arg === 'crab on' || arg === 'crab off') {
      await choosePet($, arg === 'crab on' ? 'clawd' : null)
      return { text: arg === 'crab on' ? 'Clawd is back.' : 'Clawd is resting.' }
    }
    if (arg === 'pet' || arg.startsWith('pet ')) {
      const name = arg.slice(4).trim()
      if (name === 'off' || name === 'none') return { text: await choosePet($, null) }
      const p = PETS.find(x => x.key === name || x.name.toLowerCase() === name)
      if (!p) return { text: `No pet "${name}". One of: ${PETS.map(x => x.name).join(', ')}, or off.` }
      return { text: await choosePet($, p.key) }
    }
    if (arg === 'off') return { text: await apply($, null) }
    const w = WALLS.find(x => x.key.toLowerCase() === arg || x.name.toLowerCase() === arg || x.name.toLowerCase().replace(/\s/g, '') === arg.replace(/\s/g, ''))
    if (!w) return { text: `No wallpaper "${arg}". One of: ${WALLS.map(x => x.name).join(', ')}, or off.` }
    return { text: await apply($, w.key) }
  })

  on('ui.render', { component: 'Backdrop' }, ($, e, next) => {
    if (e.props.plugin !== PLUGIN || (e.surface !== 'desktop' && e.surface !== 'mobile')) return next(e)
    const w = WALLS.find(x => `aw-${x.key}-${BUILD}` === e.props.scene)
    if (!w) return next(e)
    const { Svg } = $.ui.resolve(e)
    return <Svg source={SCENES[w.key]} alt={w.alt} isInteractive />
  })

  // the picker, with the pet on its edge; the pet alone on the prompt's edge while a wallpaper is on
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.surface !== 'desktop' && e.surface !== 'mobile') return next(e)
    const [isPicking, cur, hop, shown] = [await read($, picking), await read($, current), await read($, hops), await read($, pet)]
    const sitter = petOf(shown)
    if (!isPicking && (!cur || !sitter)) return next(e)
    const { Box, Text, Button, Svg } = $.ui.resolve(e)
    const drawn = sitter && petSvg(sitter.key, hop)
    const edge = drawn ? <Box justifyContent="flex-end" paddingX="md"><Svg source={drawn.svg} alt={sitter.name} width={drawn.width} height={drawn.height} /></Box> : <Box />
    if (!isPicking) return edge
    return (
      <Box flexDirection="column">
        {edge}
        <Box flexDirection="column" borderStyle="round" paddingX="sm" gap="xs">
          <Box flexDirection="row" justifyContent="space-between">
            <Box flexDirection="row" gap="sm"><Text bold>/wallpaper</Text><Text dimColor>Chat themes</Text></Box>
            <Box flexDirection="row" gap="sm">
              <Button key="off" label="Off" hotkey="0" dimColor onPress={() => apply($, null)} />
              <Button key="close" label="Close" role="dismiss" onPress={() => update($, picking, () => false)} />
            </Box>
          </Box>
          <Box flexDirection="row" gap="sm" flexWrap="wrap">
            {WALLS.map((w, i) => (
              <Box key={w.key} flexDirection="column" gap="xs">
                <Svg source={CARDS[w.key]} alt={w.name} width={128} height={72} />
                <Button key={w.key} label={`${w.name}${w.key === cur ? ' ✓' : ''}`} hotkey={HOTKEYS[i]} variant={w.key === cur ? 'primary' : 'secondary'} onPress={() => apply($, w.key)} />
              </Box>
            ))}
          </Box>
          <Box flexDirection="row" gap="sm" flexWrap="wrap" alignItems="center">
            <Text dimColor>Pets</Text>
            {PETS.map((p, i) => (
              <Button key={`pet-${p.key}`} label={`${p.name}${p.key === shown ? ' ✓' : ''}`} hotkey={PET_KEYS[i]} variant={p.key === shown ? 'primary' : 'secondary'} onPress={() => choosePet($, p.key)} />
            ))}
            <Button key="pet-none" label="None" hotkey="p" dimColor onPress={() => choosePet($, null)} />
          </Box>
        </Box>
      </Box>
    )
  })
}
